arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_bf69db16affb42f7887bf295ca1720e5.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <!-- Step Indicator Bar -->
        <nav class="step-indicator mb-4">
            <ol class="step-list d-flex list-unstyled justify-content-between p-0 m-0">
                @for (int i = 0; i < _stepNames.Length; i++)
                {
                    var stepIndex = i;
                    var stepNumber = i + 1;
                    var isCurrent = stepIndex == _currentStep;
                    var isCompleted = stepIndex < _currentStep;
                    var isFuture = stepIndex > _currentStep;

                    <li class="step-item text-center flex-fill @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                        @if (isCompleted)
                        {
                            <button type="button" class="btn btn-link step-btn p-0" @onclick="() => GoToStep(stepIndex)">
                                <span class="step-circle bg-success text-white">✓</span>
                                <span class="step-label d-block mt-1 text-success fw-semibold">@_stepNames[stepIndex]</span>
                            </button>
                        }
                        else
                        {
                            <div>
                                <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@stepNumber</span>
                                <span class="step-label d-block mt-1 @(isCurrent ? "text-primary fw-semibold" : "text-muted")">@_stepNames[stepIndex]</span>
                            </div>
                        }
                    </li>
                }
            </ol>
        </nav>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger" role="alert">@_errorMessage</div>
        }

        <!-- Step 1: Personal Info -->
        @if (_currentStep == 0)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Personal Information</h5></div>
                <div class="card-body">
                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input id="fullName" class="form-control" @bind="_fullName" />
                    </div>
                    <div class="mb-3">
                        <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
                        <input id="email" type="email" class="form-control" @bind="_email" />
                        @if (_emailValidating)
                        {
                            <div class="form-text text-info">Validating email…</div>
                        }
