@page "/apply"
@rendermode InteractiveServer
@using sv_bf69db16affb42f7887bf295ca1720e5.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <!-- Step Indicator Bar -->
        <nav class="step-indicator mb-4">
            <ol class="step-list d-flex list-unstyled justify-content-between p-0 m-0">
                @for (int i = 0; i < _stepNames.Length; i++)
                {
                    var stepIndex = i;
                    var stepNumber = i + 1;
                    var isCurrent = stepIndex == _currentStep;
                    var isCompleted = stepIndex < _currentStep;
                    var isFuture = stepIndex > _currentStep;

                    <li class="step-item text-center flex-fill @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                        @if (isCompleted)
                        {
                            <button type="button" class="btn btn-link step-btn p-0" @onclick="() => GoToStep(stepIndex)">
                                <span class="step-circle bg-success text-white">✓</span>
                                <span class="step-label d-block mt-1 text-success fw-semibold">@_stepNames[stepIndex]</span>
                            </button>
                        }
                        else
                        {
                            <div>
                                <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@stepNumber</span>
                                <span class="step-label d-block mt-1 @(isCurrent ? "text-primary fw-semibold" : "text-muted")">@_stepNames[stepIndex]</span>
                            </div>
                        }
                    </li>
                }
            </ol>
        </nav>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger" role="alert">@_errorMessage</div>
        }

        <!-- Step 1: Personal Info -->
        @if (_currentStep == 0)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Personal Information</h5></div>
                <div class="card-body">
                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input id="fullName" class="form-control" @bind="_fullName" />
                    </div>
                    <div class="mb-3">
                        <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
                        <input id="email" type="email" class="form-control" @bind="_email" />
                        @if (_emailValidating)
                        {
                            <div class="form-text text-info">Validating email…</div>
                        }
                    </div>
                    <div class="mb-3">
                        <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
                        <input id="phone" type="tel" class="form-control" @bind="_phone" />
                    </div>
                    <div class="mb-3">
                        <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
                        <textarea id="address" class="form-control" rows="2" @bind="_address"></textarea>
                    </div>
                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextStep" disabled="@_emailValidating">Next</button>
                    </div>
                </div>
            </div>
        }

        <!-- Step 2: Work History -->
        @if (_currentStep == 1)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Work History</h5></div>
                <div class="card-body">
                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var idx = i;
                        <fieldset class="border rounded p-3 mb-3">
                            <legend class="float-none w-auto fs-6 fw-semibold px-2">Position @(idx + 1)</legend>
                            <div class="row g-3">
                                <div class="col-md-6">
                                    <label class="form-label">Company <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="_workEntries[idx].Company" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="_workEntries[idx].Title" />
                                </div>
                                <div class="col-md-4">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" @bind="_workEntries[idx].StartDate" />
                                </div>
                                <div class="col-md-4">
                                    <label class="form-label">End Date</label>
                                    <input type="date" class="form-control" @bind="_workEntries[idx].EndDate" disabled="@_workEntries[idx].IsCurrent" />
                                </div>
                                <div class="col-md-4 d-flex align-items-end">
                                    <div class="form-check mb-2">
                                        <input class="form-check-input" type="checkbox" id="current-@idx" @bind="_workEntries[idx].IsCurrent" />
                                        <label class="form-check-label" for="current-@idx">Currently working here</label>
                                    </div>
                                </div>
                                <div class="col-12">
                                    <label class="form-label">Description</label>
                                    <textarea class="form-control" rows="2" @bind="_workEntries[idx].Description"></textarea>
                                </div>
                            </div>
                            @if (_workEntries.Count > 1)
                            {
                                <div class="mt-2 text-end">
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                                </div>
                            }
                        </fieldset>
                    }
                    <button class="btn btn-outline-secondary btn-sm mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next</button>
                    </div>
                </div>
            </div>
        }

        <!-- Step 3: References -->
        @if (_currentStep == 2)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">References</h5></div>
                <div class="card-body">
                    @for (int i = 0; i < _references.Count; i++)
                    {
                        var idx = i;
                        <fieldset class="border rounded p-3 mb-3">
                            <legend class="float-none w-auto fs-6 fw-semibold px-2">Reference @(idx + 1)</legend>
                            <div class="row g-3">
                                <div class="col-md-6">
                                    <label class="form-label">Name <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="_references[idx].Name" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="_references[idx].Relationship" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Email <span class="text-danger">*</span></label>
                                    <input type="email" class="form-control" @bind="_references[idx].Email" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                                    <input type="tel" class="form-control" @bind="_references[idx].Phone" />
                                </div>
                            </div>
                            @if (_references.Count > 2)
                            {
                                <div class="mt-2 text-end">
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                                </div>
                            }
                        </fieldset>
                    }
                    @if (_references.Count < 3)
                    {
                        <button class="btn btn-outline-secondary btn-sm mb-3" @onclick="AddReference">+ Add Reference</button>
                    }
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next</button>
                    </div>
                </div>
            </div>
        }

        <!-- Step 4: Cover Letter -->
        @if (_currentStep == 3)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Cover Letter</h5></div>
                <div class="card-body">
                    <div class="mb-3">
                        <label for="coverLetter" class="form-label">Write your cover letter</label>
                        <textarea id="coverLetter" class="form-control" rows="10" maxlength="2000"
                                  @bind="_coverLetter" @bind:event="oninput"></textarea>
                        <div class="form-text text-end">@(_coverLetter?.Length ?? 0) / 2000 characters</div>
                    </div>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next</button>
                    </div>
                </div>
            </div>
        }

        <!-- Step 5: Review & Submit -->
        @if (_currentStep == 4)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Review &amp; Submit</h5></div>
                <div class="card-body">
                    <!-- Personal Info Review -->
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h6 class="fw-bold">Personal Information</h6>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(0)">Edit</button>
                        </div>
                        <dl class="row mb-0">
                            <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                        </dl>
                    </div>
                    <hr />

                    <!-- Work History Review -->
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h6 class="fw-bold">Work History</h6>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                        </div>
                        @foreach (var entry in _workEntries)
                        {
                            <div class="ms-2 mb-2">
                                <strong>@entry.Title</strong> at @entry.Company<br />
                                <small class="text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") –
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                                </small>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mb-0 mt-1">@entry.Description</p>
                                }
                            </div>
                        }
                    </div>
                    <hr />

                    <!-- References Review -->
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h6 class="fw-bold">References</h6>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                        </div>
                        @foreach (var r in _references)
                        {
                            <div class="ms-2 mb-2">
                                <strong>@r.Name</strong> (@r.Relationship)<br />
                                <small class="text-muted">@r.Email · @r.Phone</small>
                            </div>
                        }
                    </div>
                    <hr />

                    <!-- Cover Letter Review -->
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h6 class="fw-bold">Cover Letter</h6>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                        </div>
                        <p class="ms-2 white-space-pre-wrap">@_coverLetter</p>
                    </div>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_submitting">
                            @if (_submitting)
                            {
                                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            }
                            Submit Application
                        </button>
                    </div>
                </div>
            </div>
        }
    }
    else
    {
        <!-- Confirmation -->
        <div class="card border-success">
            <div class="card-body text-center py-5">
                <div class="display-1 text-success mb-3">✓</div>
                <h3 class="text-success">Application Submitted!</h3>
                <p class="lead">Your application has been received.</p>
                <p class="fs-5">Application ID: <strong>@_applicationId</strong></p>
            </div>
        </div>
    }
</div>

<style>
    .step-circle {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 36px;
        height: 36px;
        border-radius: 50%;
        font-size: 0.875rem;
        font-weight: 600;
    }
    .step-btn {
        text-decoration: none;
    }
    .step-btn:hover .step-label {
        text-decoration: underline;
    }
    .step-label {
        font-size: 0.8rem;
    }
    .white-space-pre-wrap {
        white-space: pre-wrap;
    }
</style>

@code {
    private static readonly string[] _stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep;
    private string? _errorMessage;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private bool _emailValidating;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    // Submit
    private bool _submitting;
    private bool _submitted;
    private int _applicationId;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _errorMessage = null;
            _currentStep--;
        }
    }

    private async Task NextStep()
    {
        _errorMessage = null;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _emailValidating = true;
            StateHasChanged();
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _emailValidating = false;
            if (!emailValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
        }

        _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
                    || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _errorMessage = "All personal information fields are required.";
                    return false;
                }
                break;

            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                        || entry.StartDate == default)
                    {
                        _errorMessage = "Company, job title, and start date are required for each position.";
                        return false;
                    }
                }
                break;

            case 2:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                        || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        _errorMessage = "All fields are required for each reference.";
                        return false;
                    }
                }
                break;
        }

        return true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
    private void AddReference() { if (_references.Count < 3) _references.Add(new ReferenceModel()); }
    private void RemoveReference(int index) { if (_references.Count > 2) _references.RemoveAt(index); }

    private async Task SubmitApplication()
    {
        _submitting = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(
                _workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate,
                    e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()
            );
            var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, references, _coverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch
        {
            _errorMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            _submitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
